class VisionIntegrityV1(EventBase):
    """
    画面完整性异常（生产者 vision-engine）
    """

    camera_id: str
    type: Literal["freeze", "replay", "occlusion", "shift", "stream_lost"]
    duration_s: float = Field(..., ge=0.0)
    source: Literal["rule", "model"]
    """
    freeze、stream_lost 为确定性判定（rule）；replay、shift、occlusion 为视觉模型判定（model）
    """
    confidence: float = Field(..., ge=0.0, le=1.0)
    """
    可信度；rule 来源为 1.0
    """
    detail: str | None
    """
    可读说明，如重放匹配到的历史时刻
    """


class Camera(ContractModel):
    id: str
    """
    cam-NN，也是 go2rtc 与录像中的流名
    """
    area_id: str | None
    """
    所在场景区域；null 表示未放入任何区域，3D 中不出现（D-124）
    """
    name: str
    ip: IPv4Address | IPv6Address
    ingest: Literal["pull", "push"]
    """
    pull 为系统拉流；push 为设备推流到 rtsp://<边缘主机>:8554/<id>
    """
    source: CameraSource | None
    """
    推流时为 null
    """
    username: str | None
    password_set: bool
    """
    口令只写不读（C-ST-03）
    """
    push_password: str | None = None
    """
    推流口令（用户名 hyd）：只在新增推流摄像头或改为推流的响应中给出一次，列表中不含（V-CAM2、D-103）
    """
    pose: Pose
    calibration: list[CalibrationItem]
    """
    地面标定点 [u, v, x, y]，只经 site.yaml 初始导入；少于 4 组时按安装参数估算（D-102）
    """
    climb_lines: list[ClimbLine]
    created_at: AwareDatetime
    updated_at: AwareDatetime


class CameraList(ContractModel):
    items: list[Camera]


class CameraCreate(ContractModel):
    name: str = Field(..., max_length=40, min_length=1)
    ip: IPv4Address | IPv6Address
    ingest: Literal["pull", "push"]
    source: CameraSource | None = None
    """
    拉流时必填
    """
    username: Username | None = None
    password: SecretStr | None = Field(None, max_length=128)
    pose: Pose
    climb_lines: list[ClimbLine] | None = None


class CameraUpdate(ContractModel):
    name: str | None = Field(None, max_length=40, min_length=1)
    ip: IPv4Address | IPv6Address | None = None
    ingest: Literal["pull", "push"] | None = None
    source: CameraSource | None = None
    username: Username | None = None
    password: SecretStr | None = Field(None, max_length=128)
    """
    省略表示不修改
    """
    clear_password: bool | None = None
    pose: Pose | None = None
    climb_lines: list[ClimbLine] | None = None


class CameraInfo(ContractModel):
    stream: str
    """
    go2rtc 流名
    """
    area_id: str | None
    """
    所在场景区域，null 表示未放置
    """
    mapping: Literal["calibrated", "estimated", "none"]
    """
    地面映射：calibrated 按 ≥ 4 组标定点；estimated 按安装参数估算（D-102）；none 时 state 为 uncalibrated
    """
    pose: Pose
    calibration: list[CalibrationItem]
    """
    标定点 [u, v, x, y]：像素坐标与平面坐标；少于 4 组时按安装参数估算（D-102）
    """
    homography: Homography | None
    reproj_error_m: ReprojErrorM | None


class IncidentList(ContractModel):
    items: list[Incident]


class IncidentReport(ContractModel):
    """
    溯源报告 AI 区（architecture.md §12、G-12）；事实区由报告服务从结构化数据组装，不经过 LLM
    """

    summary: str = Field(..., max_length=300)
    attack_chain: list[AttackStep] = Field(..., max_length=10)
    impact: list[Impact] = Field(..., max_length=10)
    recommendations: list[Recommendation] = Field(..., max_length=10)
    """
    只作文字建议，不进入任何执行路径（G-03）
    """
    confidence: Literal["low", "medium", "high"]


class ReportInvestigation(ContractModel):
    """
    生成报告时值班员判定的快照（FR-1106）
    """

    verdict: InvestigationVerdict
    provider: InvestigationProvider | None
    finished_at: AwareDatetime


class ProviderTestResult(ContractModel):
    checks: list[ProviderCheck]
    health: Literal["ok", "slow", "failed"]
    """
    连通或模型不通过为 failed；连通延迟超过 3000 ms 为 slow；结构化输出不影响分档（D-084）
    """
    tested_at: AwareDatetime
    suggested_base_url: str | None
    """
    原地址的 /models 返回 404、补上 /v1 后可用时给出，由管理员采用
    """
    suggested_models: list[str] = Field(..., max_length=3)
    """
    配置的模型不在列表中时，名称最相近的候选
    """


class EgressStats(ContractModel):
    window_s: Literal[600]
    count: int = Field(..., ge=0)
    targets: list[EgressTarget]


class InvestigationFrame(ContractModel):
    """
    AI 安全值班员调查流中的一帧：调查步骤、最终判定或失败（spec.md US-11）
    """

    incident_id: str
    seq: int = Field(..., ge=0)
    """
    同一关联事件内从 0 递增
    """
    kind: Literal["step", "verdict", "failed"]
    step: InvestigationStep | None
    """
    kind=step 时有值
    """
    verdict: InvestigationVerdict | None
    """
    kind=verdict 时有值
    """
    error: str | None
    """
    kind=failed 时的原因，如"无可用供应商"
    """
    provider: InvestigationProvider | None
    """
    本次调查使用的供应商；无可用供应商时为 null
    """


class VisionTrackV1(EventBase, Track):
    """
    检出目标的位置更新，字段即 Track 实体（生产者 vision-engine）
    """


class Line(RootModel[list[Point]]):
    model_config = {"allow_inf_nan": False}
    root: list[Point] = Field(..., min_length=2)


class Polygon(RootModel[list[Point]]):
    model_config = {"allow_inf_nan": False}
    root: list[Point] = Field(..., min_length=3)


class VisionBehavior(RootModel[VisionBehaviorV1]):
    model_config = {"allow_inf_nan": False}
    root: VisionBehaviorV1


class SecurityAlert(RootModel[SecurityAlertV1]):
    model_config = {"allow_inf_nan": False}
    root: SecurityAlertV1


class VisionIntegrity(RootModel[VisionIntegrityV1]):
    model_config = {"allow_inf_nan": False}
    root: VisionIntegrityV1


class Device(ContractModel):
    id: str
    name: str
    """
    显示名称（摄像头登记表的 name）
    """
    type: Literal["camera", "nvr", "switch"]
    ip: IPv4Address | IPv6Address
    mode: Literal["bypass", "host_probe"]
    state: Literal[
        "normal",
        "offline",
        "uncalibrated",
        "physical_alert",
        "cyber_alert",
        "both",
        "pending_action",
        "contained",
        "notify_only",
    ]
    """
    ui.md §5.1，由 api-server 计算
    """
    alert_severity: Literal["critical", "high", "medium", "low"] | None
    """
    state 为 cyber_alert 或 both 期间收到的最高告警等级，其余状态为 null（ui.md §5.1、V-A1）
    """
    camera: CameraInfo | None
    """
    type 为 camera 时必有
    """


class ReportAi(ContractModel):
    """
    AI 区（V-AI1），与事实区物理分隔；供应商信息为生成时的快照
    """

    content: IncidentReport
    unverified: list[str]
    """
    无法在证据或本地知识库中溯源的实体，保留并弱化显示（FR-503、C-LLM-06、V-AI3、D-086）
    """
    provider_name: str
    model: str
    network: Network
    """
    public 表示发送前已脱敏（C-LLM-03）
    """


class ReportTimelineEntry(ContractModel):
    """
    kind 与 event 为 null 表示证据缺失：事件已超出 24 小时保留或未收到
    """

    event_id: UUID
    kind: Literal["security_alert", "behavior", "integrity"] | None
    event: SecurityAlert | VisionBehavior | VisionIntegrity | None


class LlmProvider(ContractModel):
    """
    不含 API Key，只返回末 4 位（C-LLM-15）
    """

    id: str
    name: str
    preset: Preset
    base_url: str
    """
    OpenAI 兼容 base URL
    """
    api_key_last4: ApiKeyLast4 | None
    model: str
    network: Network
    network_overridden: bool
    """
    管理员改判过网络位置
    """
    structured_output: Literal["json_schema", "json_object", "none"] | None
    """
    由测试连接探测；未测试时为 null
    """
    timeout_s: int = Field(..., ge=1)
    enabled: bool
    order: int = Field(..., ge=0)
    last_test: ProviderTestResult | None
    """
    最近一次测试连接的结果，卡片据此显示健康分档与延迟（D-084）；未测试时为 null
    """
    usage_today: ProviderUsage


class LlmProviderList(ContractModel):
    items: list[LlmProvider]


class AiInvestigationV1(EventBase, InvestigationFrame):
    """
    AI 安全值班员调查流，字段即 InvestigationFrame（生产者 api-server，D-087）
    """


class VisionTrack(RootModel[VisionTrackV1]):
    model_config = {"allow_inf_nan": False}
    root: VisionTrackV1


class Surface(ContractModel):
    class_: Literal["road", "sidewalk", "floor", "grass", "earth"] = Field(..., alias="class")
    polygon: Polygon


class Wall(ContractModel):
    class_: Literal["wall", "building", "fence", "railing", "board"] = Field(..., alias="class")
    line: Line
    height_m: float = Field(..., gt=0.0)


class Object(ContractModel):
    class_: Literal["table", "chair", "cabinet", "sofa", "bed", "furniture", "street_furniture"] = (
        Field(..., alias="class")
    )
    polygon: Polygon
    height_m: float = Field(..., gt=0.0)


class Marking(ContractModel):
    class_: Literal["crosswalk", "lane"] = Field(..., alias="class")
    polygon: Polygon


class SceneFrame(ContractModel):
    """
    摄像头画面中识别到的环境，已投影到平面（spec.md FR-909）：只含平面坐标（米）的多边形与线段，不含图像；只在生成场景初稿时识别一次，不持久化（D-133、architecture.md §12）。地面、物体与标线的多边形合计不超过 64 个
    """

    camera_id: str
    surfaces: list[Surface]
    """
    地面色块
    """
    walls: list[Wall]
    """
    立面：沿墙脚线挤出，高度按类别取默认值。board 为黑板（含投影幕、公告板），line 为其下方的墙脚线，板面离地 0.9 m、高 height_m
    """
    objects: list[Object]
    """
    物体的底面轮廓：桌、椅、柜、沙发、床以家具模型沿轮廓排开；其余家具（furniture）与街道设施由轮廓挤出 height_m 高的低矮立体块
    """
    trees: list[Tree]
    """
    植被：树干底部中心
    """
    markings: list[Marking]
    """
    路面区域内的白色标线
    """


class Site(ContractModel):
    id: str
    name: str
    width_m: float = Field(..., gt=0.0)
    height_m: float = Field(..., gt=0.0)
    areas: list[SceneArea]
    devices: list[Device]


class ReportFacts(ContractModel):
    """
    事实区，全部来自结构化数据，不经过 LLM（V-AI1）
    """

    incident: Incident
    devices: list[ReportDevice]
    """
    关联事件涉及的设备，取自站点登记
    """
    timeline: list[ReportTimelineEntry]
    """
    按 hit_path 顺序的命中事件
    """
    executions: list[PlaybookExecution]
    """
    该关联事件的处置执行，各自的最新状态
    """


class AiInvestigation(RootModel[AiInvestigationV1]):
    model_config = {"allow_inf_nan": False}
    root: AiInvestigationV1


class VisionSceneV1(EventBase, SceneFrame):
    """
    一台摄像头当前画面中识别到的环境，字段即 SceneFrame（生产者 vision-engine）；只在 hyd.vision.scene_reply.v1 中按请求返回，不单独发布（D-133）
    """


class Report(ContractModel):
    id: str
    incident_id: str
    facts: ReportFacts
    ai: ReportAi | None
    """
    AI 区；模板模式下为 null
    """
    investigation: ReportInvestigation | None
    """
    AI 区引用的值班员判定，模型与模板报告都有（D-089）；生成时调查尚未给出判定为 null
    """
    source: Literal["llm", "template"]
    provider_id: str | None
    degraded_reason: str | None
    """
    模板报告的原因，如"未启用任何模型供应商"（FR-502、V-AI5）；source 为 llm 时为 null
    """
    reviewed_by: str | None
    reviewed_at: AwareDatetime | None
    created_at: AwareDatetime


class ReportList(ContractModel):
    items: list[Report]


class VisionScene(RootModel[VisionSceneV1]):
    model_config = {"allow_inf_nan": False}
    root: VisionSceneV1


class SceneAreaFrames(ContractModel):
    frames: list[VisionScene]
    """
    区域内各摄像头当前画面的识别帧，坐标为区域内坐标，按摄像头编号排列
    """
    unavailable: list[SceneUnavailable]
    """
    区域内没有识别帧的摄像头与原因，按摄像头编号排列
    """
    stale: list[str] = Field(..., deprecated=True)
    """
    unavailable 中的摄像头编号；下次升契约主版本时删除
    """
